package com.agriconnect.notification;import java.util.*;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/notifications")class NotificationController{private final JdbcClient db;NotificationController(JdbcClient d){db=d;}private long uid(){return Long.parseLong(SecurityContextHolder.getContext().getAuthentication().getName());}@GetMapping List<Map<String,Object>>list(){return db.sql("select id,type,title,message,reference_type as \"referenceType\",reference_id as \"referenceId\",read_at as \"readAt\",created_at as \"createdAt\" from notifications where recipient_user_id=:u order by created_at desc limit 100").param("u",uid()).query().listOfRows();}@PatchMapping("/{id}/read")Map<String,Object>read(@PathVariable long id){if(db.sql("update notifications set read_at=coalesce(read_at,now())where id=:id and recipient_user_id=:u").param("id",id).param("u",uid()).update()==0)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND,"Notification not found");return db.sql("select id,type,title,message,read_at as \"readAt\" from notifications where id=:id").param("id",id).query().singleRow();}}
